"""Produce a single Windows EXE: ZIP core plus solid LZMA2 Git payload."""
from pathlib import Path
import hashlib
import subprocess
import zipfile
import runpy
import sys

import py7zr

ROOT = Path(__file__).resolve().parents[1]
BUNDLE = ROOT / 'outputs/SmartClock-Windows'
WORK = ROOT / 'outputs/onefile-build'
RELEASE = ROOT / 'outputs/desktop-release'


def include(path):
    """Remove generated bytecode and optional development UI/docs only."""
    parts = path.parts
    if '__pycache__' in parts or path.suffix.lower() in ('.pyc', '.pyo', '.pdb'):
        return False
    if parts[:3] in (('runtime', 'Lib', 'idlelib'), ('runtime', 'Lib', 'turtledemo'), ('runtime', 'Lib', 'pydoc_data')):
        return False
    return path.as_posix() not in ('SmartClock.exe', 'READ-ME.txt')


def build(payload_only=False):
    WORK.mkdir(parents=True, exist_ok=True)
    RELEASE.mkdir(parents=True, exist_ok=True)
    git_archive = WORK / 'git.7z'
    get_mingit = runpy.run_path(str(ROOT / 'desktop/bundle_git.py'))['get_mingit']
    git_source = get_mingit()
    print('Compressing bundled Git with solid LZMA2...', flush=True)
    with py7zr.SevenZipFile(git_archive, 'w', filters=[{'id': py7zr.FILTER_LZMA2, 'preset': 7}]) as archive:
        archive.writeall(git_source, 'git')
    payload = WORK / 'payload.zip'
    with zipfile.ZipFile(payload, 'w', zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in sorted(BUNDLE.rglob('*')):
            relative = path.relative_to(BUNDLE)
            if relative.parts[0] == 'git' or not path.is_file() or not include(relative):
                continue
            if relative.as_posix() == 'firmware/secrets.yaml':
                raise RuntimeError('Private settings must not enter the application')
            archive.write(path, relative.as_posix())
        archive.write(ROOT / 'desktop/prepare_runtime.py', 'prepare_runtime.py')
        archive.write(ROOT / 'desktop/smoke_test.py', 'smoke_test.py')
        archive.write(git_archive, 'git.7z', compress_type=zipfile.ZIP_STORED)
    with payload.open('rb') as stream:
        identity = hashlib.file_digest(stream, 'sha256').hexdigest()[:24]
    (WORK / 'payload-id.txt').write_text(identity, encoding='ascii')
    if payload_only:
        return payload
    launcher = WORK / 'onefile_launcher.cs'
    launcher.write_text((ROOT / 'desktop/onefile_launcher.cs').read_text(encoding='utf-8').replace('PAYLOAD_ID', identity), encoding='utf-8')
    output = RELEASE / 'SmartClock-Windows-x64.exe'
    compiler = Path('C:/Windows/Microsoft.NET/Framework64/v4.0.30319/csc.exe')
    subprocess.run([str(compiler), '/nologo', '/target:winexe', '/optimize+',
                    '/reference:System.Windows.Forms.dll', '/reference:System.Drawing.dll',
                    '/reference:System.IO.Compression.dll',
                    '/resource:' + str(payload) + ',payload.zip', '/out:' + str(output), str(launcher)], check=True)
    (WORK / 'payload-id.txt').write_text(identity, encoding='ascii')
    with output.open('rb') as stream:
        checksum = hashlib.file_digest(stream, 'sha256').hexdigest()
    output.with_suffix('.sha256').write_text(f'{checksum}  {output.name}\n', encoding='ascii')
    print(f'Single EXE: {output} ({output.stat().st_size / 1048576:.1f} MiB)', flush=True)
    return output


if __name__ == '__main__':
    build('--payload-only' in sys.argv)
